CREATE TYPE "PublicationStatus" AS ENUM ('DRAFT','SCHEDULED','PUBLISHED','ARCHIVED');
CREATE TYPE "BillingPeriod" AS ENUM ('MONTH_1','MONTH_3','MONTH_6','MONTH_12');
CREATE TABLE "Category" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"names" JSONB NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Channel" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"names" JSONB NOT NULL,"searchText" TEXT NOT NULL,"description" JSONB,"logoUrl" TEXT,"languageCode" TEXT NOT NULL,"countryCode" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"status" "PublicationStatus" NOT NULL DEFAULT 'DRAFT',"webAvailable" BOOLEAN NOT NULL DEFAULT false,"featured" BOOLEAN NOT NULL DEFAULT false,"publishedAt" TIMESTAMP(3),"scheduledFor" TIMESTAMP(3),"archivedAt" TIMESTAMP(3),"categoryId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Channel_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ChannelRight" ("id" TEXT NOT NULL,"channelId" TEXT NOT NULL,"countryCode" TEXT NOT NULL,"webAllowed" BOOLEAN NOT NULL DEFAULT false,"mobileAllowed" BOOLEAN NOT NULL DEFAULT false,"tvAllowed" BOOLEAN NOT NULL DEFAULT false,"validFrom" TIMESTAMP(3) NOT NULL,"validUntil" TIMESTAMP(3) NOT NULL,"approved" BOOLEAN NOT NULL DEFAULT false,"contractRef" TEXT,CONSTRAINT "ChannelRight_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ChannelPrice" ("id" TEXT NOT NULL,"channelId" TEXT NOT NULL,"currency" TEXT NOT NULL,"period" "BillingPeriod" NOT NULL,"amountMinor" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "ChannelPrice_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Package" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"names" JSONB NOT NULL,"searchText" TEXT NOT NULL,"description" JSONB,"badge" JSONB,"status" "PublicationStatus" NOT NULL DEFAULT 'DRAFT',"featured" BOOLEAN NOT NULL DEFAULT false,"sortOrder" INTEGER NOT NULL DEFAULT 0,"maxDevices" INTEGER NOT NULL DEFAULT 1,"maxConcurrentStreams" INTEGER NOT NULL DEFAULT 1,"allowedCountries" TEXT[],"publishedAt" TIMESTAMP(3),"scheduledFor" TIMESTAMP(3),"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Package_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PackageChannel" ("packageId" TEXT NOT NULL,"channelId" TEXT NOT NULL,CONSTRAINT "PackageChannel_pkey" PRIMARY KEY ("packageId","channelId"));
CREATE TABLE "PackagePrice" ("id" TEXT NOT NULL,"packageId" TEXT NOT NULL,"currency" TEXT NOT NULL,"period" "BillingPeriod" NOT NULL,"amountMinor" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "PackagePrice_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug"); CREATE UNIQUE INDEX "Channel_slug_key" ON "Channel"("slug"); CREATE INDEX "Channel_status_sortOrder_idx" ON "Channel"("status","sortOrder"); CREATE INDEX "Channel_countryCode_languageCode_idx" ON "Channel"("countryCode","languageCode");
CREATE UNIQUE INDEX "ChannelRight_channelId_countryCode_key" ON "ChannelRight"("channelId","countryCode"); CREATE INDEX "ChannelRight_countryCode_approved_validUntil_idx" ON "ChannelRight"("countryCode","approved","validUntil"); CREATE UNIQUE INDEX "ChannelPrice_channelId_currency_period_key" ON "ChannelPrice"("channelId","currency","period");
CREATE UNIQUE INDEX "Package_slug_key" ON "Package"("slug"); CREATE INDEX "Package_status_sortOrder_idx" ON "Package"("status","sortOrder"); CREATE UNIQUE INDEX "PackagePrice_packageId_currency_period_key" ON "PackagePrice"("packageId","currency","period");
ALTER TABLE "Channel" ADD CONSTRAINT "Channel_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ChannelRight" ADD CONSTRAINT "ChannelRight_channelId_fkey" FOREIGN KEY ("channelId") REFERENCES "Channel"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ChannelPrice" ADD CONSTRAINT "ChannelPrice_channelId_fkey" FOREIGN KEY ("channelId") REFERENCES "Channel"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PackageChannel" ADD CONSTRAINT "PackageChannel_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "Package"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PackageChannel" ADD CONSTRAINT "PackageChannel_channelId_fkey" FOREIGN KEY ("channelId") REFERENCES "Channel"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PackagePrice" ADD CONSTRAINT "PackagePrice_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "Package"("id") ON DELETE CASCADE ON UPDATE CASCADE;
